with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الرصد الجوي الرأسي والمسابير والليدار','المسابير الراديوية والمخططات الديناميكية الحرارية وقياسات الرياح والسحب والطبقة الحدية والليدار والرادار الرأسي وضبط جودة الملفات الرأسية.',60,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'المسابير والتحليل الديناميكي الحراري',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تقنيات الرصد الرأسي وجودة البيانات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('upper-air-observation-system','منظومة الرصد الجوي العلوي','بنية القياسات الرأسية وتكامل مصادرها','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يصف الرصد الجوي العلوي حالة الغلاف الجوي فوق السطح عبر ملفات رأسية للحرارة والرطوبة والرياح والضغط. ويجمع بين المسابير والطائرات والرادار والليدار والأقمار الصناعية وفق دقة وتغطية مختلفة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"منظومة الرصد الجوي العلوي","text":"ارسم مخططاً يبين تكامل الرصد السطحي والرأسي والفضائي. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم مخططاً يبين تكامل الرصد السطحي والرأسي والفضائي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8160,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('radiosonde-instrumentation','أجهزة المسبار الراديوي','المستشعرات والمرسل ونظام تحديد الموقع','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحمل المسبار مستشعرات لقياس الحرارة والرطوبة والضغط أو الارتفاع، ويرسل البيانات أثناء الصعود. تؤثر الاستجابة الزمنية والتهوية والإشعاع والمعايرة في جودة الملف الرأسي."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"أجهزة المسبار الراديوي","text":"حدد مصادر الخطأ المحتملة في مستشعر الحرارة والرطوبة أثناء الصعود. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد مصادر الخطأ المحتملة في مستشعر الحرارة والرطوبة أثناء الصعود."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8170,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('radiosonde-ascent-trajectory','مسار صعود المسبار','الرياح والانجراف والتمثيل المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"لا يصعد المسبار عمودياً بالضرورة؛ تحمله الرياح في مسار مائل يتغير مع الارتفاع. لذلك تمثل القياسات مساراً متحركاً، ويجب مراعاة موقع القياس عند تفسير البنية الرأسية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مسار صعود المسبار","text":"اشرح كيف يؤثر انجراف المسبار في مقارنة ملفه مع محطة أرضية. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يؤثر انجراف المسبار في مقارنة ملفه مع محطة أرضية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8180,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('pressure-altitude-conversion','تحويل الضغط إلى ارتفاع','المعادلة الهيبسومترية والطبقات الجوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يرتبط تغير الضغط بالارتفاع من خلال معادلات الاتزان الهيدروستاتيكي وقانون الغاز، وتستخدم درجة الحرارة الافتراضية في العلاقة الهيبسومترية. يعتمد التحويل على تمثيل متوسط حرارة الطبقة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحويل الضغط إلى ارتفاع","text":"وضح لماذا يتطلب تحويل فرق الضغط إلى سمك طبقي معرفة متوسط الحرارة. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"وضح لماذا يتطلب تحويل فرق الضغط إلى سمك طبقي معرفة متوسط الحرارة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8190,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('thermodynamic-diagram-construction','بناء المخططات الديناميكية الحرارية','تمثيل الحرارة والرطوبة والضغط','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع المخططات مثل Skew-T وLog-P متغيرات المسبار في تمثيل واحد يسمح بفحص الاستقرار والرطوبة ومستويات التكاثف والحمل الحراري. تتطلب القراءة معرفة خطوط الحرارة الجافة والرطبة ونسب الخلط."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"بناء المخططات الديناميكية الحرارية","text":"حدد المعلومات التي يمكن استخلاصها من ملف حرارة ونقطة ندى على مخطط Skew-T. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد المعلومات التي يمكن استخلاصها من ملف حرارة ونقطة ندى على مخطط Skew-T."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8200,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('lifting-condensation-level','مستوى التكاثف بالرفع','تقارب حرارة الهواء ونقطة الندى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل مستوى التكاثف بالرفع الارتفاع التقريبي الذي يصل إليه الهواء الصاعد إلى الإشباع عند تبريده أدياباتياً. يستخدم لتقدير قاعدة السحب مع مراعاة أن الواقع يتأثر بالخلط والرفع غير المثالي."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مستوى التكاثف بالرفع","text":"قدر نوعياً أثر اتساع الفرق بين الحرارة ونقطة الندى عند السطح على ارتفاع القاعدة. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قدر نوعياً أثر اتساع الفرق بين الحرارة ونقطة الندى عند السطح على ارتفاع القاعدة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8210,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('convective-available-potential-energy','الطاقة المتاحة للحمل الحراري','الطفو الموجب وتكامل فرق الحرارة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعبر CAPE عن الطاقة المرتبطة بالطفو الموجب لحزمة هوائية مقارنة بالبيئة ضمن طبقة محددة. تعتمد على مسار الحزمة وطريقة رفعها والملف الحراري والرطوبي، ولا تكفي وحدها لتحديد شدة العاصفة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الطاقة المتاحة للحمل الحراري","text":"فسر لماذا لا يعني ارتفاع CAPE وحده أن عاصفة شديدة ستحدث. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا لا يعني ارتفاع CAPE وحده أن عاصفة شديدة ستحدث."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8220,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('convective-inhibition','كبح الحمل الحراري','الطفو السالب والغطاء الحراري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل CIN الطاقة اللازمة لتجاوز طبقة تعيق صعود الحزمة. قد تمنع طبقة دافئة أو جافة بدء الحمل حتى مع وجود طاقة حمل كامنة أعلى منها، بينما يمكن للرفع واسع النطاق إضعاف الكبح."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"كبح الحمل الحراري","text":"قارن بيئتين لهما CAPE متقاربة وCIN مختلفة. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بيئتين لهما CAPE متقاربة وCIN مختلفة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8230,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('parcel-theory-limitations','نظرية الحزمة وحدودها','الخلط والسحب والتمثيل البيئي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم نظرية الحزمة لتبسيط صعود جزء من الهواء ومقارنته بالبيئة، لكنها تهمل أو تبسط الخلط والسحب والقص والتغير المكاني. يجب تفسير مؤشرات الاستقرار ضمن السياق الديناميكي الكامل."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"نظرية الحزمة وحدودها","text":"حدد ثلاث فرضيات في نظرية الحزمة قد لا تتحقق في العاصفة الحقيقية. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد ثلاث فرضيات في نظرية الحزمة قد لا تتحقق في العاصفة الحقيقية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8240,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
('wind-shear-profiling','تحليل قص الرياح الرأسي','تغير السرعة والاتجاه مع الارتفاع','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يصف القص الرأسي تغير متجه الرياح مع الارتفاع، ويرتبط بتنظيم الحمل الحراري وانتقال الزخم والاضطراب. يتطلب تحليله ملفات موثوقة واتفاقاً على الطبقة المرجعية وطريقة حساب القص."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل قص الرياح الرأسي","text":"قارن القص الاتجاهي والقص السرعي من ملف رياح افتراضي. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن القص الاتجاهي والقص السرعي من ملف رياح افتراضي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8250,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'المسابير والتحليل الديناميكي الحراري'),
