('wind-profiler-radar','رادار قياس الرياح الرأسية','تشتت الإشارة واستخراج متجه الرياح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم رادارات الرياح الرأسية تشتت الموجات عن اضطرابات معامل الانكسار لتقدير الرياح على ارتفاعات متعددة. تتغير جودة القياس مع التردد والطقس والتداخل وخصائص الطبقة الجوية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"رادار قياس الرياح الرأسية","text":"قارن مزايا الرادار الرأسي والليدار في الرصد المستمر. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مزايا الرادار الرأسي والليدار في الرصد المستمر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8280,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('ceilometer-cloud-base','قياس قاعدة السحب بالسيلومتر','النبضات الليزرية والارتداد الخلفي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس السيلومتر ارتفاع قاعدة السحب من زمن عودة النبضة الليزرية المتشتتة. يمكنه رصد طبقات متعددة أحياناً، لكنه لا يقدم وحده وصفاً كاملاً لسمك السحابة أو طورها."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"قياس قاعدة السحب بالسيلومتر","text":"فسر كيف يمكن لجهاز سيلومتر أن يسجل أكثر من طبقة سحابية. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر كيف يمكن لجهاز سيلومتر أن يسجل أكثر من طبقة سحابية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8290,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('boundary-layer-profiler','رصد الطبقة الحدية الجوية','الخلط الرأسي والانقلاب الحراري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتغير الطبقة الحدية بفعل التسخين السطحي والتبريد والرياح والخلط والغطاء السحابي. يساعد دمج ملفات الحرارة والرطوبة والرياح في تحديد ارتفاعها وتطورها اليومي."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"رصد الطبقة الحدية الجوية","text":"حلل سيناريو اختلاف ارتفاع الطبقة الحدية بين النهار والليل. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل سيناريو اختلاف ارتفاع الطبقة الحدية بين النهار والليل."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8300,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('inversion-detection','كشف الانقلابات الحرارية رأسياً','الاستقرار وتراكم الملوثات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يظهر الانقلاب عندما تزداد الحرارة مع الارتفاع ضمن طبقة، ما يعزز الاستقرار ويحد من الخلط الرأسي. يجب تحديد سمك الانقلاب وقوته وارتفاع قاعدته وربطها بالرياح والهباء."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"كشف الانقلابات الحرارية رأسياً","text":"اشرح كيف يؤثر انقلاب سطحي في تشتت الملوثات قرب الأرض. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يؤثر انقلاب سطحي في تشتت الملوثات قرب الأرض."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8310,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('upper-air-data-quality-control','ضبط جودة بيانات الرصد العلوي','الفحوص الفيزيائية والاتساق الرأسي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب ضبط الجودة فحص حدود القيم ومعدلات التغير والاتساق بين الحرارة والرطوبة والضغط والارتفاع والرياح، إضافة إلى كشف الانقطاعات والانجراف وأخطاء التوقيت."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"ضبط جودة بيانات الرصد العلوي","text":"صمم قائمة تحقق آلية لملف مسبار راديوي قبل إدخاله إلى قاعدة البيانات. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم قائمة تحقق آلية لملف مسبار راديوي قبل إدخاله إلى قاعدة البيانات."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8320,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('sounding-intercomparison','مقارنة المسابير ومصادر الملفات الرأسية','التحيز والتزامن والاختلاف المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتطلب المقارنة بين المسابير أو بينها وبين الليدار والرادار مراعاة اختلاف توقيت القياس وموقعه ودقة الارتفاع واستجابة المستشعر. يمكن استخدام مقاييس الانحياز والتشتت والارتباط بحسب المتغير."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مقارنة المسابير ومصادر الملفات الرأسية","text":"اقترح بروتوكول مقارنة بين ملفي مسبارين أطلقا بفاصل زمني قصير. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح بروتوكول مقارنة بين ملفي مسبارين أطلقا بفاصل زمني قصير."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8330,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('data-assimilation-upper-air','استيعاب بيانات الرصد الجوي العلوي','قيود الرصد ودوال التأثير','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر الملفات الرأسية في تحليل النماذج العددية لأنها تقيد بنية الحرارة والرطوبة والرياح. يعتمد وزن الرصد على خطئه وتمثيل النموذج والارتباطات المكانية والرأسية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"استيعاب بيانات الرصد الجوي العلوي","text":"وضح لماذا قد يكون لخطأ رصد في طبقة معينة تأثير في التحليل المجاور رأسياً. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"وضح لماذا قد يكون لخطأ رصد في طبقة معينة تأثير في التحليل المجاور رأسياً."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8340,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات'),
('upper-air-network-operations','تشغيل شبكة الرصد الجوي العلوي','التوقيت والتغطية والاستمرارية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعتمد تشغيل الشبكة على جدولة الإطلاقات وتوحيد الإجراءات ومراقبة جودة الأجهزة ونقل البيانات وتوثيق الأعطال. تؤثر كثافة الرصد وتزامنه في قيمة الملفات لتحليل الحالة والتنبؤ."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يعتمد الرصد الرأسي على تحويل إشارة المستشعر أو زمن انتقالها أو تشتتها إلى متغير جوي قابل للتفسير. وتتطلب هذه العملية معرفة هندسة القياس واستجابة الجهاز والظروف البيئية ومعايرة سلسلة التحويل من الإشارة الخام إلى المنتج النهائي."},{"type":"heading","text":"المتغيرات والبيانات"},{"type":"list","items":["الحرارة والرطوبة والضغط والارتفاع والرياح.","التوقيت والموقع ومسار القياس وهندسة الجهاز.","استجابة المستشعر والمعايرة وحدود الكشف.","الملف الرأسي ومعدل أخذ العينات والفجوات.","بيانات مرجعية مستقلة لفحص الاتساق والانحياز."]},{"type":"heading","text":"منهجية العمل"},{"type":"list","items":["حدد نوع الجهاز والمتغير الذي يقيسه مباشرة.","راجع المعايرة ووحدات القياس والتوقيت والموقع.","افحص الاتساق الفيزيائي والرأسي ومعدلات التغير.","قارن مع مصادر مستقلة متزامنة قدر الإمكان.","وثق حدود التغطية والتمثيل المكاني واللايقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تشغيل شبكة الرصد الجوي العلوي","text":"ضع مؤشرات تشغيلية لمتابعة اكتمال ملفات الرصد العلوي في شبكة وطنية. أنشئ تحليلاً افتراضياً واضحاً، وافصل بين ما يقيسه الجهاز مباشرة وما يتم اشتقاقه حسابياً."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع مؤشرات تشغيلية لمتابعة اكتمال ملفات الرصد العلوي في شبكة وطنية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مسار القياس الرأسي عمودياً تماماً دون فحص الانجراف.","إهمال استجابة المستشعر أو أثر الإشعاع والتهوية.","مقارنة قياسات مختلفة التوقيت أو المقياس دون مواءمة.","تفسير منتج مشتق كأنه قياس مباشر.","إغفال حدود الكشف أو التغطية في الطبقات العليا."]},{"type":"callout","text":"قيمة الملف الرأسي لا تعتمد على كثافة النقاط فقط؛ بل على المعايرة والتوقيت والتمثيل المكاني وسلامة سلسلة معالجة البيانات."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يمثل الرصد الرأسي حلقة أساسية بين القياسات السطحية والتحليل العددي. ويعتمد الاستخدام التشغيلي الموثوق على ضبط الجودة وتكامل الأجهزة وفهم حدود كل تقنية."}]}'::jsonb,8350,55,'["شرح مبدأ الرصد أو التحليل الرأسي المرتبط بالموضوع","تحديد متطلبات البيانات والمعايرة وضبط الجودة","تفسير الملفات الرأسية ضمن سياق الأرصاد التشغيلية"]'::jsonb,'تقنيات الرصد الرأسي وجودة البيانات')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='المسابير والتحليل الديناميكي الحراري' then u1.id else u2.id end,'الرصد الجوي الرأسي والمسابير والليدار',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;